package ru.mtproxy.picker;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.Color;import android.widget.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Independent personal collection: imports merge, never replace user entries. */
public final class ManualActivity extends Activity {
 final ArrayList<ManualEntry> entries=new ArrayList<>();final ExecutorService worker=Executors.newSingleThreadExecutor();LinearLayout page,rows;TextView status;boolean busy,dead;int visible=60;CancellableOperation operation;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(Color.WHITE);return v;}
 Button action(String label,Runnable run){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(0xff343434);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffffb44d));b.setOnClickListener(v->{if(!busy)run.run();});return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff343434);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(20),dp(20),dp(20),dp(20));page.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(20),dp(16)+i.getSystemWindowInsetTop(),dp(20),dp(16)+i.getSystemWindowInsetBottom());return i;});scroll.addView(page);setContentView(scroll);Button home=action("На главный экран",()->finish());home.setOnClickListener(v->finish());page.addView(home);page.addView(text("Манул · мои прокси",24));page.addView(text("Добавляйте ссылки или импортируйте выбранные источники. Список сохраняется на телефоне.",14));page.addView(action("Добавить ссылкой",()->editor()));page.addView(action("Из списка «Халява»",()->{List<ManualEntry> cached=ManualEntry.parse(getSharedPreferences("MainActivity",0).getString("list",""));int added=merge(cached);save();render();status.setText(cached.isEmpty()?"Сначала получите список в «Халяве»":"Добавлено: "+added);}));page.addView(action("Получить списки",()->importSources()));page.addView(action("Проверить пинг",()->probeAll()));status=text("",14);page.addView(status);rows=new LinearLayout(this);rows.setOrientation(1);page.addView(rows);try{JSONArray saved=new JSONArray(getSharedPreferences("manual",0).getString("entries","[]"));for(int i=0;i<saved.length();i++){JSONObject row=saved.getJSONObject(i);List<ManualEntry> parsed=ManualEntry.parse(row.getString("link"));if(!parsed.isEmpty()){ManualEntry e=parsed.get(0);e.ms=row.optLong("ms",-2);entries.add(e);}}}catch(Exception ignored){}render();}
 void editor(){EditText input=new EditText(this);input.setHint("tg://proxy, t.me/proxy или t.me/webproxy\nМожно вставить несколько ссылок");input.setMinLines(3);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Добавить прокси").setView(input).setNegativeButton("Отмена",null).setPositiveButton("Добавить",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{List<ManualEntry> parsed=ManualEntry.parse(input.getText().toString());if(parsed.isEmpty()){input.setError("Не найдены корректные ссылки с server, port и secret");return;}int added=merge(parsed);save();render();status.setText("Добавлено: "+added);dialog.dismiss();}));dialog.show();}
 int merge(List<ManualEntry> next){Set<String> known=new HashSet<>();for(ManualEntry e:entries)known.add(e.link);int added=0;for(ManualEntry e:next)if(entries.size()<3000&&known.add(e.link)){entries.add(e);added++;}return added;}
 void save(){try{JSONArray data=new JSONArray();for(ManualEntry e:entries)data.put(new JSONObject().put("link",e.link).put("ms",e.ms));getSharedPreferences("manual",0).edit().putString("entries",data.toString()).apply();}catch(Exception ignored){}}
 void importSources(){boolean[] selected=new boolean[MainActivity.SOURCE_NAMES.length];for(int i=0;i<selected.length;i++)selected[i]=getSharedPreferences("MainActivity",0).getBoolean("source_"+i,i==0);new AlertDialog.Builder(this).setTitle("Импорт из источников").setMultiChoiceItems(MainActivity.SOURCE_NAMES,selected,(d,i,checked)->selected[i]=checked).setNegativeButton("Отмена",null).setPositiveButton("Получить",(d,w)->{boolean any=false;for(boolean b:selected)any|=b;if(!any){status.setText("Выберите хотя бы один источник");return;}busy=true;status.setText("Загрузка источников…");operation=new CancellableOperation();worker.execute(()->{ArrayList<ManualEntry> result=new ArrayList<>();ArrayList<String> failed=new ArrayList<>();for(int i=0;i<selected.length&&!dead;i++)if(selected[i])try{List<ManualEntry> parsed=ManualEntry.parse(MainActivity.download(MainActivity.SOURCE_URLS[i],operation));if(parsed.isEmpty())throw new Exception();result.addAll(parsed);}catch(Exception e){failed.add(MainActivity.SOURCE_NAMES[i]);}runOnUiThread(()->{if(dead)return;busy=false;int added=merge(result);save();render();status.setText("Добавлено: "+added+(failed.isEmpty()?"":". Не загрузились: "+android.text.TextUtils.join(", ",failed)));});});}).show();}
 void probeAll(){if(entries.isEmpty()){status.setText("Сначала добавьте прокси");return;}busy=true;status.setText("Проверка…");worker.execute(()->{ProbeEngine.refreshDns();ExecutorService pool=Executors.newFixedThreadPool(16);ArrayList<Future<Long>> results=new ArrayList<>();for(ManualEntry e:entries)results.add(pool.submit(()->ProbeEngine.measure(e.host,e.port,1500)));for(int i=0;i<results.size()&&!dead;i++)try{entries.get(i).ms=results.get(i).get();}catch(Exception ignored){}pool.shutdownNow();runOnUiThread(()->{if(dead)return;busy=false;entries.sort((a,b)->Long.compare(a.ms<0?Long.MAX_VALUE:a.ms,b.ms<0?Long.MAX_VALUE:b.ms));save();render();status.setText("Проверка завершена. WEB-прокси: измерен TCP 443, не работа Telegram.");});});}
 void render(){rows.removeAllViews();if(entries.isEmpty())rows.addView(text("Пока пусто. Добавьте свою первую ссылку.",16));int count=Math.min(visible,entries.size());for(int i=0;i<count;i++){ManualEntry e=entries.get(i);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(12),dp(14),dp(12));card.setBackgroundColor(0xff454545);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);rows.addView(card,lp);card.addView(text(e.host+":"+e.port+(e.web?" · WEB":" · MTProto"),17));TextView rating=text(PingQuality.label(e.ms)+(e.ms>=0?" · "+e.ms+" мс":""),14);rating.setTextColor(PingQuality.color(e.ms));card.addView(rating);card.addView(action("Подключить",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(e.link)));}catch(ActivityNotFoundException ex){status.setText("Установите Telegram");}}));card.addView(action("Удалить",()->{entries.remove(e);save();render();}));}if(count<entries.size())rows.addView(action("Показать ещё",()->{visible+=60;render();}));}
 @Override public void onBackPressed(){if(busy){Toast.makeText(this,"Дождитесь окончания операции",Toast.LENGTH_SHORT).show();return;}super.onBackPressed();}
 @Override protected void onDestroy(){dead=true;if(operation!=null)operation.cancel();worker.shutdownNow();super.onDestroy();}
}

